package usercode
import ("context"; "fmt"; "github.com/zr-hebo/script-agent/sdk")
type Task struct { sdk.BaseTask }
func New() sdk.TaskRunner { return &Task{} }
func (t *Task) Run(ctx context.Context, params map[string]any) sdk.Outcome {
 if err := ctx.Err(); err != nil { return sdk.Outcome{Status:sdk.StatusCancelled,Error:err} }; fmt.Println("processing", params["cluster_uuid"]); return sdk.Outcome{Status:sdk.StatusSucceeded,Data:params}
}
